-- Rollback for cl-docket-metadata-fields-v2.sql (cl-docket-metadata-fields/2026-10-27.v2).
-- Restores title, item, detail, text and filters of every cl_docket_metadata row from the private
-- before-image table, and the dataset metadata from its backup. search_vector is regenerated by the
-- existing corpus_records_search_vector_trg because title and text are written.
-- Only rows that carry the released fields (cells ? 'case_name') are restored, so rows that were never
-- released (the 15 CourtListener-blocked dockets) are untouched. Rows changed by a later contract after
-- the release are restored too; check the ledger before rolling back if another contract has run since.
-- The backup tables are kept (drop them only after the lead confirms the rollback is not needed).
begin;

do $$ begin
  if to_regclass('corpus_ingest.cl_docket_metadata_fields_backup_20261027') is null
     or to_regclass('corpus_ingest.cl_docket_metadata_fields_dataset_backup_20261027') is null then
    raise exception 'backup tables missing; nothing to roll back from';
  end if;
end $$;

with restored as (
  update public.corpus_records r
     set title = b.title, item = b.item, detail = b.detail, text = b.text, filters = b.filters
    from corpus_ingest.cl_docket_metadata_fields_backup_20261027 b
   where r.dataset = 'cl_docket_metadata' and r.id = b.id
     and r.item -> 'cells' ? 'case_name'
  returning r.id
)
select count(*) as rows_restored from restored;

update public.corpus_datasets d
   set metadata = b.metadata
  from corpus_ingest.cl_docket_metadata_fields_dataset_backup_20261027 b
 where d.id = b.dataset and d.id = 'cl_docket_metadata';

do $$ begin
  if exists (select 1 from public.corpus_records r
             join corpus_ingest.cl_docket_metadata_fields_backup_20261027 b on b.id = r.id
             where r.dataset = 'cl_docket_metadata'
               and md5(jsonb_build_array(r.title, r.item, r.detail, r.text, r.filters)::text) <> b.fields_md5) then
    raise exception 'a row still differs from its before-image; rollback aborted';
  end if;
end $$;
commit;

-- Verify (read-only): expect docket_placeholder_titles = 186940 and with_caption = 0.
select count(*) as total,
       count(*) filter (where title like 'Docket %') as docket_placeholder_titles,
       count(*) filter (where item -> 'cells' ? 'case_name') as with_caption
from public.corpus_records where dataset = 'cl_docket_metadata';
